using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
namespace BuildingFlow.Infrastructure;
public sealed class WebsiteInquiryStore(BuildingFlowDbContext db,TimeProvider clock,SessionContextStore contexts):IWebsiteInquiryStore{
 private IQueryable<WebsiteSite> Admin(Guid p,AccessScope a)=>db.Set<WebsiteSite>().Where(s=>s.PropertyId==p&&s.IsEnabled&&db.Properties.Any(x=>x.Id==p&&x.IsEnabled&&(a.ReadAll||db.PropertyMemberships.Any(m=>m.PropertyId==p&&m.UserId==a.UserId&&m.IsEnabled)))&&(!contexts.Enabled||contexts.ManagementProperties("MANAGER").Any(x=>x.PropertyId==p)));
 private static void Invalid()=>throw new RequestValidationException(new(){["inquiry"]=[ErrorCatalog.InquiryRejected.Create()]});
 private static InquiryDto Dto(WebsiteInquiry x)=>new(x.Id,x.ListingId,x.FullName,x.Phone,x.Email,x.Message,x.PrivacyNoticeVersion,x.Status,x.RetainUntil,x.Version);
 public async Task<IReadOnlyList<InquiryDto>?> List(Guid p,AccessScope a,CancellationToken t){if(!await Admin(p,a).AnyAsync(t))return null;var now=clock.GetUtcNow();return (await db.Set<WebsiteInquiry>().Where(x=>x.PropertyId==p&&x.IsEnabled&&x.RetainUntil>now).OrderByDescending(x=>x.CreatedAt).Take(500).ToArrayAsync(t)).Select(Dto).ToArray();}
 public async Task<InquiryDto?> Update(Guid p,Guid id,InquiryUpdate r,AccessScope a,CancellationToken t){if(r.Status is not("NEW" or "HANDLED" or "SPAM")||r.Version<1)Invalid();await using var tx=await db.Database.BeginTransactionAsync(t);if(!await Admin(p,a).AnyAsync(t))return null;await db.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM properties WHERE id={p} FOR UPDATE",t);if(!await Admin(p,a).AnyAsync(t))return null;var now=clock.GetUtcNow();var x=await db.Set<WebsiteInquiry>().SingleOrDefaultAsync(x=>x.PropertyId==p&&x.Id==id&&x.IsEnabled&&x.RetainUntil>now,t);if(x is null)return null;if(x.Version!=r.Version)throw new HierarchyConflictException(ErrorCatalog.RecordChanged.Create());x.SetStatus(r.Status);db.Entry(x).Property(x=>x.IsEnabled).IsModified=true;await db.SaveChangesAsync(t);await tx.CommitAsync(t);return Dto(x);}
 public async Task Retain(CancellationToken t){
 var now=clock.GetUtcNow();while(true){var rows=await db.Set<WebsiteInquiry>().Where(x=>x.IsEnabled&&x.RetainUntil<=now).Take(500).ToArrayAsync(t);if(rows.Length==0)break;foreach(var x in rows)x.Anonymize();await db.SaveChangesAsync(t);db.ChangeTracker.Clear();}
 // Public reads independently filter expiry; the worker also records the eventual state transition.
 while(true){var ids=await db.Set<PropertyListing>().Where(x=>x.Status=="PUBLISHED"&&x.PublishUntil<=now).OrderBy(x=>x.PropertyId).Take(500).Select(x=>x.Id).ToArrayAsync(t);if(ids.Length==0)break;await using var tx=await db.Database.BeginTransactionAsync(t);var properties=await db.Set<PropertyListing>().Where(x=>ids.Contains(x.Id)).Select(x=>x.PropertyId).Distinct().OrderBy(x=>x).ToArrayAsync(t);foreach(var p in properties)await db.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM properties WHERE id={p} FOR UPDATE",t);var rows=await db.Set<PropertyListing>().Where(x=>ids.Contains(x.Id)&&x.Status=="PUBLISHED"&&x.PublishUntil<=now).ToArrayAsync(t);foreach(var x in rows){x.Transition("EXPIRE",null,now);db.Entry(x).Property(v=>v.IsEnabled).IsModified=true;db.Add(new ListingEvent(x.PropertyId,x.Id,"EXPIRE",null,x.Version+1));}await db.SaveChangesAsync(t);await tx.CommitAsync(t);db.ChangeTracker.Clear();}
 }
}
